import{_ as e,H as l,f as a,i as s}from"./chunks/framework.DLd0CbzH.js";const x=JSON.parse('{"title":"Конкурентный анализ — Agelto","description":"","frontmatter":{"type":"analysis","tags":["agelto","competitors","market"],"created":"2026-05-31T00:00:00.000Z","updated":"2026-06-13T00:00:00.000Z"},"headers":[],"relativePath":"01_Business/02_Competitive_Analysis.md","filePath":"01_Business/02_Competitive_Analysis.md"}'),i={name:"01_Business/02_Competitive_Analysis.md"};function n(r,t,d,o,g,h){return l(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="конкурентныи-анализ-—-agelto" tabindex="-1">Конкурентный анализ — Agelto <a class="header-anchor" href="#конкурентныи-анализ-—-agelto" aria-label="Permalink to &quot;Конкурентный анализ — Agelto&quot;">​</a></h1><h2 id="ландшафт-2026" tabindex="-1">Ландшафт (2026) <a class="header-anchor" href="#ландшафт-2026" aria-label="Permalink to &quot;Ландшафт (2026)&quot;">​</a></h2><p>Рынок тендерных сервисов РФ — системы <strong>первого поколения</strong> (атрибутивный поиск):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Игрок</th><th style="text-align:left;">Суть</th><th style="text-align:left;">Слабость</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Seldon</strong></td><td style="text-align:left;">Крупнейший агрегатор ЕИС</td><td style="text-align:left;">Поиск по названию контракта/ИНН, нет парсинга смет</td></tr><tr><td style="text-align:left;"><strong>Тендерплан</strong></td><td style="text-align:left;">Уведомления о тендерах</td><td style="text-align:left;">То же, атрибутивный поиск, нет AI</td></tr><tr><td style="text-align:left;"><strong>Контур.Закупки</strong></td><td style="text-align:left;">Экосистема Контур</td><td style="text-align:left;">Широкий охват, но нет глубокой декомпозиции смет</td></tr><tr><td style="text-align:left;"><strong>Bicotender</strong></td><td style="text-align:left;">Мониторинг закупок</td><td style="text-align:left;">Базовый поиск, нет семантики</td></tr><tr><td style="text-align:left;"><strong>РТС-тендер</strong></td><td style="text-align:left;">Электронная торговая площадка</td><td style="text-align:left;">Площадка, не аналитик</td></tr></tbody></table><p><strong>Незанятая ниша:</strong> никто не делает глубокий AI-парсинг смет + семантический матчинг с каталогом поставщика.</p><hr><h2 id="дифференциация-agelto" tabindex="-1">Дифференциация Agelto <a class="header-anchor" href="#дифференциация-agelto" aria-label="Permalink to &quot;Дифференциация Agelto&quot;">​</a></h2><p><strong>Agelto — система второго поколения (Deep AI Parsing):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Конкуренты: находят ТЕНДЕР → поставщик сам читает смету (часы/дни)</span></span>
<span class="line"><span>Agelto:     находит СТРОКУ В СМЕТЕ → матчит с прайсом → доставляет в CRM (секунды)</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Параметр</th><th style="text-align:left;">Конкуренты (1 поколение)</th><th style="text-align:left;">Agelto (2 поколение)</th></tr></thead><tbody><tr><td style="text-align:left;">Точность поиска</td><td style="text-align:left;">40–50% (ключевые слова)</td><td style="text-align:left;">&gt;92% (векторный поиск)</td></tr><tr><td style="text-align:left;">Глубина анализа</td><td style="text-align:left;">Заголовок тендера</td><td style="text-align:left;">Каждая строка сметы</td></tr><tr><td style="text-align:left;">Форматы</td><td style="text-align:left;">Только метаданные ЕИС</td><td style="text-align:left;">PDF, Excel, Word (OCR+AI)</td></tr><tr><td style="text-align:left;">Интеграция</td><td style="text-align:left;">Нет / email</td><td style="text-align:left;">API → CRM (Bitrix24, amoCRM)</td></tr><tr><td style="text-align:left;">Языковой комплаенс</td><td style="text-align:left;">Нет</td><td style="text-align:left;">Авто-кириллизация брендов</td></tr><tr><td style="text-align:left;">Матчинг с прайсом</td><td style="text-align:left;">Нет</td><td style="text-align:left;">pgvector (косинусное сходство)</td></tr></tbody></table><hr><h2 id="барьеры-входа-защита-от-копирования" tabindex="-1">Барьеры входа (защита от копирования) <a class="header-anchor" href="#барьеры-входа-защита-от-копирования" aria-label="Permalink to &quot;Барьеры входа (защита от копирования)&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">Смена барьера после переноса каталога в [[TcenZor]]</p><p>Решением [[ADR-001_Catalog_From_TcenZor|ADR-001]] эталонный каталог/MDM ведётся в каталоге-хабе [[TcenZor]], а не внутри Agelto. Барьер входа Agelto смещается с «владения каталогом» на <strong>сметный матчинг + накопленный golden dataset вердиктов</strong> (что само по себе сильнее: каталог копируем, а размеченные вердикты по реальным сметам — нет).</p></div><ol><li><strong>Технологический</strong> — конвейер парсинга неструктурированных смет ЕИС (LayoutLM + OCR + NLP + pgvector) требует 1.5–2 года разработки и CAPEX, сопоставимый с нашим бюджетом R&amp;D</li><li><strong>Данных</strong> — <strong>golden dataset размеченных вердиктов</strong> по реальным сметам (цель: 50 000+ строк, F-MDM-3) накапливается с каждой верификацией. Эталонный каталог общий (из [[TcenZor]]), но качество матчинга «смета → эталон» обучается только на наших данных</li><li><strong>Доменная экспертиза</strong> — обученные модели на специфических коллекциях (ЖБИ, кабель, металл) и понимание сметной традиции нельзя просто купить</li></ol><hr><h2 id="swot" tabindex="-1">SWOT <a class="header-anchor" href="#swot" aria-label="Permalink to &quot;SWOT&quot;">​</a></h2><h3 id="сильные-стороны" tabindex="-1">Сильные стороны <a class="header-anchor" href="#сильные-стороны" aria-label="Permalink to &quot;Сильные стороны&quot;">​</a></h3><ul><li>ИИ-стек с точностью матчинга &gt;92% vs 40–50% у конкурентов</li><li>Глубокая нишевая экспертиза (сметы строительства)</li><li>Низкий порог безубыточности (&lt; 0.1% SAM)</li><li>Соответствие государственному вектору импортозамещения</li></ul><h3 id="слабые-стороны" tabindex="-1">Слабые стороны <a class="header-anchor" href="#слабые-стороны" aria-label="Permalink to &quot;Слабые стороны&quot;">​</a></h3><ul><li>Высокий CAPEX на R&amp;D (GPU, Senior AI-инженеры)</li><li>Зависимость от качества PDF в ЕИС</li><li>Низкая узнаваемость бренда на старте</li></ul><h3 id="возможности" tabindex="-1">Возможности <a class="header-anchor" href="#возможности" aria-label="Permalink to &quot;Возможности&quot;">​</a></h3><ul><li>Государственный заказ на цифровизацию строительства</li><li>Интеграция с ГосТех — стать официальным AI-модулем для госзаказчиков</li><li>Экспансия в BIM — связь цифровой модели здания с рынком материалов</li><li>Функция антикоррупционного аудита смет (проверка цен vs ФГИС ЦС)</li></ul><h3 id="угрозы" tabindex="-1">Угрозы <a class="header-anchor" href="#угрозы" aria-label="Permalink to &quot;Угрозы&quot;">​</a></h3><ul><li>Крупные игроки (Seldon) могут скопировать упрощенную AI-версию</li><li>ЕИС может изменить политику доступа к документам для парсинга</li><li>Кадровый дефицит NLP-специалистов</li></ul><hr><h2 id="pestel" tabindex="-1">PESTEL <a class="header-anchor" href="#pestel" aria-label="Permalink to &quot;PESTEL&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Фактор</th><th style="text-align:left;">Влияние на Agelto</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P</strong> Political</td><td style="text-align:left;">Господдержка цифрового суверенитета — попутный ветер</td></tr><tr><td style="text-align:left;"><strong>E</strong> Economic</td><td style="text-align:left;">Волатильность цен стимулирует автоматизацию анализа смет</td></tr><tr><td style="text-align:left;"><strong>S</strong> Social</td><td style="text-align:left;">Новое поколение менеджеров 30–45 лет предпочитает SaaS + автоматизацию</td></tr><tr><td style="text-align:left;"><strong>T</strong> Tech</td><td style="text-align:left;">LLM и pgvector доступны — реализовать Agelto стало возможным</td></tr><tr><td style="text-align:left;"><strong>E</strong> Environmental</td><td style="text-align:left;">ESG-тренд: Agelto помогает подбирать локальных поставщиков → меньше логистики</td></tr><tr><td style="text-align:left;"><strong>L</strong> Legal</td><td style="text-align:left;">44-ФЗ/223-ФЗ ужесточают прозрачность — Agelto = инструмент комплаенса</td></tr></tbody></table>`,27)])])}const y=e(i,[["render",n]]);export{x as __pageData,y as default};
